const SKS_LOGO_DATA_URL =
  'data:image/png;base64,';

export interface AdmissionFormData {
  admissionNumber: string;
  applicationDate: string;
  admissionDate: string;
  academicYear: string;
  programName: string;
  courseName: string | null;
  yearOfStudy: number | null;
  studentType: string | null;
  admissionQuota: string | null;

  collegeLogo: string | null;
  collegeName: string | null;
  collegeTrustLine: string | null;
  collegeAddress: string | null;
  collegePhone: string | null;
  collegeEmail: string | null;

  studentName: string;
  dateOfBirth: string | null;
  gender: string | null;
  bloodGroup: string | null;
  physicalDisability: boolean | null;
  aadharNumber: string | null;
  nationality: string | null;
  religion: string | null;
  communityCategory: string | null;
  caste: string | null;

  phone: string | null;
  email: string | null;
  postalAddress: string | null;
  street: string | null;
  city: string | null;
  district: string | null;
  state: string | null;
  pincode: string | null;

  fatherName: string | null;
  fatherPhone: string | null;
  fatherEmail: string | null;
  motherName: string | null;
  motherPhone: string | null;
  motherEmail: string | null;

  qualifications: Array<{
    qualificationType: string;
    schoolName: string | null;
    universityOrBoard: string | null;
    monthAndYearOfPassing: string | null;
    percentage: number | null;
    totalMarks: number | null;
    majorSubject: string | null;
  }>;

  documents: Array<{
    documentType: string;
    verificationStatus: string;
  }>;

  passportPhotoUrl?: string | null;

  declarationPlace: string | null;
  declarationDate: string | null;
  parentConsentGiven: boolean | null;
  applicantConsentGiven: boolean | null;
}

function fmtDate(iso: string | null | undefined): string {
  if (!iso) return '';
  const d = new Date(iso + (iso.includes('T') ? '' : 'T00:00:00'));
  return d.toLocaleDateString('en-IN', { day: '2-digit', month: 'long', year: 'numeric' });
}

function fmtEnum(value: string | null | undefined): string {
  if (!value) return '';
  return value.replace(/_/g, ' ').replace(/\b\w/g, (c) => c.toUpperCase());
}

function fmtDocType(code: string): string {
  const labels: Record<string, string> = {
    AADHAR_CARD: 'Aadhar Card',
    PAN_CARD: 'PAN Card',
    BIRTH_CERTIFICATE: 'Birth Certificate',
    TRANSFER_CERTIFICATE: 'School Transfer Certificate',
    COLLEGE_OR_SCHOOL_TC: 'College Transfer Certificate',
    MIGRATION_CERTIFICATE: 'Migration Certificate',
    CONDUCT_CERTIFICATE: 'Conduct Certificate',
    COMMUNITY_CERTIFICATE: 'Community Certificate',
    INCOME_CERTIFICATE: 'Income Certificate',
    MEDICAL_CERTIFICATE: 'Medical Certificate / Fitness',
    MEDICAL_FITNESS: 'Medical Fitness Certificate',
    TENTH_MARKSHEET: '10th Marksheet',
    ELEVENTH_MARKSHEET: '11th Marksheet',
    TWELFTH_MARKSHEET: '12th Marksheet',
    SSLC_MARKSHEET: 'SSLC / 10th Marksheet',
    HSC_MARKSHEET: 'HSC / 12th Marksheet',
    GENUINENESS_CERTIFICATE: 'Genuineness Certificate',
    ELIGIBILITY_CERTIFICATE: 'Eligibility Certificate',
    FIRST_GRADUATE_CERTIFICATE: 'First Graduate Certificate',
    SCANNED_SIGNATURE: 'Scanned Signature',
    DEGREE_CERTIFICATE: 'Degree Certificate',
    PROVISIONAL_CERTIFICATE: 'Provisional Certificate',
    PASSPORT_PHOTO: 'Passport Size Photograph',
    SIGNED_AFFIDAVIT: 'Signed Affidavit / Consent Form',
    ANTI_RAGGING_FORM: 'Anti-Ragging Form',
    COUNSELLING_LETTER: 'Counselling Allotment Letter',
    NEET_SCORECARD: 'NEET Scorecard',
    NATIVITY_CERTIFICATE: 'Nativity Certificate',
    OBC_CERTIFICATE: 'OBC Certificate',
    SC_ST_CERTIFICATE: 'SC/ST Certificate',
    DISABILITY_CERTIFICATE: 'Disability Certificate',
    BANK_PASSBOOK: 'Bank Passbook / Account Details',
    SCHOLARSHIP_LETTER: 'Scholarship Letter',
    OTHER: 'Other Document',
  };
  return labels[code] ?? fmtEnum(code);
}

function fmtCompactVerificationStatus(status: string): string {
  const map: Record<string, string> = {
    VERIFIED: 'Verified',
    UPLOADED: 'Pending',
    REJECTED: 'Rejected',
    NOT_UPLOADED: 'Not Submitted',
  };
  return map[status] ?? fmtEnum(status);
}

function documentStatusColor(status: string): string {
  if (status === 'VERIFIED') return '#166534';
  if (status === 'REJECTED') return '#991b1b';
  if (status === 'NOT_UPLOADED') return '#64748b';
  return '#92400e';
}

function fieldRow(label: string, value: string | null | undefined, cols = 1): string {
  const v = (value ?? '').trim();
  const span = cols > 1 ? ' style="width:100%;"' : '';
  return `<div class="field"${span}>
    <div class="fl">${label}</div>
    <div class="fv">${v || '&nbsp;'}</div>
  </div>`;
}

function documentChecklistCells(
  doc: AdmissionFormData['documents'][number] | undefined,
  index: number,
): string {
  if (!doc) return '<td class="doc-empty" colspan="4">&nbsp;</td>';
  const isVerified = doc.verificationStatus === 'VERIFIED';
  const isRejected = doc.verificationStatus === 'REJECTED';
  const tickBox = isVerified ? '&#10003;' : isRejected ? '&#10007;' : '';
  const statusColor = documentStatusColor(doc.verificationStatus);
  return `<td class="doc-num">${index + 1}</td>
    <td class="doc-name">${fmtDocType(doc.documentType)}</td>
    <td class="doc-collected" style="color:${statusColor};">${tickBox}</td>
    <td class="doc-status" style="color:${statusColor};">${fmtCompactVerificationStatus(doc.verificationStatus)}</td>`;
}

function buildDocumentChecklistRows(documents: AdmissionFormData['documents']): string {
  if (!documents.length) {
    return '<tr><td colspan="8" class="doc-empty-state">No documents on record</td></tr>';
  }

  const rowCount = Math.ceil(documents.length / 2);
  return Array.from({ length: rowCount }, (_, rowIndex) => {
    const left = documents[rowIndex];
    const right = documents[rowIndex + rowCount];
    return `<tr>
      ${documentChecklistCells(left, rowIndex)}
      ${documentChecklistCells(right, rowIndex + rowCount)}
    </tr>`;
  }).join('');
}

function safeFileNamePart(value: string): string {
  return (
    value
      .trim()
      .replace(/[^a-z0-9]+/gi, '_')
      .replace(/^_+|_+$/g, '') || 'Student'
  );
}


function buildAdmissionFormHtml(
  data: AdmissionFormData,
  autoPrint: boolean,
  pdfRender = false,
): string {
  const docRows = buildDocumentChecklistRows(data.documents);

  const addressParts = [
    data.postalAddress,
    data.street,
    data.city,
    data.district,
    data.state,
    data.pincode,
  ]
    .filter(Boolean)
    .join(', ');

  const genderLabel =
    data.gender === 'MALE'
      ? 'Male'
      : data.gender === 'FEMALE'
        ? 'Female'
        : data.gender === 'OTHER'
          ? 'Other'
          : '';

  const studentTypeLabel =
    data.studentType === 'DAY_SCHOLAR'
      ? 'Day Scholar'
      : data.studentType === 'HOSTELER'
        ? 'Hosteler'
        : '';

  const quotaLabel =
    data.admissionQuota === 'MANAGEMENT'
      ? 'Management'
      : data.admissionQuota === 'COUNSELLING'
        ? 'Counselling'
        : '';

  const parentConsent =
    data.parentConsentGiven === true ? 'Yes' : data.parentConsentGiven === false ? 'No' : '';
  const studentConsent =
    data.applicantConsentGiven === true ? 'Yes' : data.applicantConsentGiven === false ? 'No' : '';
  const physicalDisability =
    data.physicalDisability === true ? 'Yes' : data.physicalDisability === false ? 'No' : '';

  return `<!DOCTYPE html>
<html lang="en"${pdfRender ? ' class="pdf-render"' : ''}>
<head>
<meta charset="UTF-8"/>
<title>Admission Form — ${data.studentName}</title>
<style>
  @page { size: A4 portrait; margin: 0; }
  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

  html { background: #fff; }
  body {
    font-family: 'Times New Roman', Times, serif;
    font-size: 10.2px;
    line-height: 1.28;
    color: #000;
    background: #fff;
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
    width: 794px;
  }
  .page-body { padding: 22px 30px; box-sizing: border-box; }

  /* Screen-only preview styles — NOT applied during pdf-render iframe capture */
  @media screen {
    html:not(.pdf-render) { background: #888; padding: 20px; min-height: 100vh; }
    body:not(.pdf-render) {
      margin: 0 auto;
      box-shadow: 0 2px 16px rgba(0,0,0,.4);
      min-height: 1060px;
      display: flex;
      flex-direction: column;
    }
    body:not(.pdf-render) .page-body { flex: 1; display: flex; flex-direction: column; }
    body:not(.pdf-render) .form-footer { margin-top: auto; }
  }

  /* ── HEADER ── */
  .page-header {
    display: flex; align-items: flex-start; gap: 12px;
    border-bottom: 2.5px double #1a237e;
    padding-bottom: 6px; margin-bottom: 5px;
  }
  .logo { width: 64px; height: 64px; flex-shrink: 0; object-fit: contain; }
  .college-info { flex: 1; }
  .college-name {
    font-size: 16px; font-weight: 900; color: #1a237e;
    text-transform: uppercase; letter-spacing: 0.5px; line-height: 1.2;
  }
  .college-sub { font-size: 9.4px; color: #222; margin-top: 3px; line-height: 1.45; }
  .form-badge {
    align-self: center;
    border: 2px solid #1a237e; padding: 5px 12px;
    font-size: 10px; font-weight: 900; letter-spacing: 2.5px;
    text-transform: uppercase; color: #1a237e; white-space: nowrap;
  }

  /* ── SECTIONS ── */
  .section { margin-bottom: 5px; }
  .section-hdr {
    background: #1a237e; color: #fff;
    padding: 3px 7px; font-size: 8.6px; font-weight: bold;
    letter-spacing: 1.5px; text-transform: uppercase;
  }
  .section-body { border: 1px solid #9ba8c4; border-top: none; padding: 5px 7px; }

  /* ── FIELD GRID (flexbox — html2canvas does not support CSS Grid) ── */
  .field-grid { display: flex; flex-wrap: wrap; }
  .field-grid .field { box-sizing: border-box; padding-right: 8px; margin-bottom: 4px; }
  .fg-2 .field  { width: 50%; }
  .fg-3 .field  { width: 33.33%; }
  .fg-4 .field  { width: 25%; }
  .field { display: flex; flex-direction: column; }
  .fl {
    font-size: 7.8px; font-weight: bold; color: #333;
    text-transform: uppercase; letter-spacing: 0.5px; margin-bottom: 1px;
  }
  .fv { border-bottom: 1px solid #777; min-height: 14px; font-size: 10.8px; padding: 1px 2px; line-height: 1.25; }

  /* ── PERSONAL SECTION ── */
  .personal-row { display: flex; gap: 10px; align-items: center; }
  .personal-fields { flex: 1; }
  .photo-placeholder {
    width: 78px; flex-shrink: 0; border: 1px dashed #777; height: 95px;
    display: flex; flex-direction: column; align-items: center; justify-content: center;
    text-align: center; color: #555; font-size: 8.6px; line-height: 1.45; font-style: italic;
  }
  .photo-placeholder .ph-icon { font-size: 18px; margin-bottom: 3px; color: #ccc; }
  .passport-photo { width: 78px; height: 95px; object-fit: cover; border: 1px solid #777; flex-shrink: 0; }

  /* ── TABLES ── */
  table { width: 100%; border-collapse: collapse; }
  thead th {
    background: #dde3f0; color: #1a237e;
    font-size: 8.4px; font-weight: bold; text-transform: uppercase;
    letter-spacing: 0.4px; padding: 3px 4px;
    border: 1px solid #9ba8c4; text-align: left;
  }
  tbody td { padding: 2.4px 4px; border: 1px solid #c5cbd8; font-size: 9.2px; }
  tbody tr:nth-child(even) td { background: #f5f6fa; }
  .tac { text-align: center; }
  .fw { font-weight: bold; }
  .empty-state { text-align: center; color: #888; font-style: italic; }

  /* ── DOCUMENT CHECKLIST ── */
  .doc-checklist-table { table-layout: fixed; }
  .doc-checklist-table thead th { padding: 2.4px 3px; font-size: 7.6px; text-align: center; }
  .doc-checklist-table tbody td { padding: 2px 3px; font-size: 8.7px; }
  .doc-num { text-align: center; font-weight: bold; }
  .doc-name { word-break: break-word; }
  .doc-collected { text-align: center; font-weight: bold; }
  .doc-status { text-align: center; font-size: 8px; font-weight: bold; }
  .doc-empty { background: #fff !important; border-color: #e2e8f0; }
  .doc-empty-state { text-align: center; color: #888; font-style: italic; padding: 6px; }

  /* ── DECLARATION ── */
  .decl-text { font-size: 10.2px; line-height: 1.45; margin-bottom: 6px; text-align: justify; }
  .consent-row { display: flex; gap: 24px; margin-bottom: 5px; }
  .consent-item { display: flex; align-items: center; gap: 5px; font-size: 10px; }
  .consent-box {
    width: 13px; height: 13px; border: 1.5px solid #444;
    display: inline-flex; align-items: center; justify-content: center;
    font-size: 9px; font-weight: bold;
  }
  .decl-meta { display: flex; flex-wrap: wrap; margin-top: 4px; }
  .decl-meta .field { width: 50%; box-sizing: border-box; padding-right: 8px; margin-bottom: 4px; }

  /* ── SIGNATURE BLOCK ── */
  .sig-section { margin-top: 12px; }
  .sig-row { display: flex; justify-content: space-between; align-items: flex-end; }
  .sig-block { text-align: center; width: 28%; }
  .sig-space { height: 28px; }
  .sig-line { border-top: 1px solid #000; padding-top: 2px; font-size: 9px; }
  .sig-seal {
    border: 1.5px dashed #999; height: 48px;
    display: flex; align-items: center; justify-content: center;
    font-size: 8.5px; color: #777;
  }

  /* ── FOOTER ── */
  .form-footer {
    margin-top: 10px; padding-top: 5px;
    border-top: 1px solid #9ba8c4;
    font-size: 8px; color: #555;
    display: flex; justify-content: space-between;
  }

  /* ── PAGE BREAK GUARD ── */
  .section, .sig-section { break-inside: avoid; page-break-inside: avoid; }
</style>
</head>
<body${pdfRender ? ' class="pdf-render"' : ''}>
<div class="page-body">

<!-- HEADER -->
<div class="page-header">
  <img class="logo" src="${data.collegeLogo ?? SKS_LOGO_DATA_URL}" alt="${data.collegeName ?? 'College'} Logo" />
  <div class="college-info">
    <div class="college-name">${data.collegeName ?? 'SKS College Of Nursing'}</div>
    <div class="college-sub">
      ${data.collegeTrustLine ? `${data.collegeTrustLine}<br/>` : ''}
      ${data.collegeAddress ? `${data.collegeAddress}<br/>` : ''}
      ${data.collegePhone ? `Phone: ${data.collegePhone}` : 'Phone:'}
      &nbsp;&nbsp;|&nbsp;&nbsp;
      ${data.collegeEmail ? `Email: ${data.collegeEmail}` : 'Email:'}
    </div>
  </div>
  <div class="form-badge">Admission&nbsp;Form</div>
</div>

<!-- ADMISSION DETAILS -->
<div class="section">
  <div class="section-hdr">Admission Details</div>
  <div class="section-body">
    <div class="field-grid fg-4">
      ${fieldRow('Admission Number', data.admissionNumber)}
      ${fieldRow('Application Date', fmtDate(data.applicationDate))}
      ${fieldRow('Admission Date', fmtDate(data.admissionDate))}
      ${fieldRow('Academic Year', data.academicYear)}
      ${fieldRow('Programme', data.programName)}
      ${fieldRow('Course / Specialisation', data.courseName)}
      ${fieldRow('Student Type', studentTypeLabel)}
      ${fieldRow('Admission Quota', quotaLabel || fmtEnum(data.admissionQuota))}
    </div>
  </div>
</div>

<!-- PERSONAL DETAILS -->
<div class="section">
  <div class="section-hdr">Personal Details</div>
  <div class="section-body">
    <div class="personal-row">
      <div class="personal-fields">
        <div class="field-grid fg-2" style="margin-bottom:4px;">
          ${fieldRow('Full Name', data.studentName, 2)}
        </div>
        <div class="field-grid fg-3">
          ${fieldRow('Date of Birth', fmtDate(data.dateOfBirth))}
          ${fieldRow('Gender', genderLabel)}
          ${fieldRow('Blood Group', data.bloodGroup)}
          ${fieldRow('Physical Disability', physicalDisability)}
          ${fieldRow('Aadhar Number', data.aadharNumber)}
          ${fieldRow('Nationality', data.nationality)}
          ${fieldRow('Religion', data.religion)}
          ${fieldRow('Community Category', data.communityCategory)}
          ${fieldRow('Caste', data.caste)}
        </div>
      </div>
      ${data.passportPhotoUrl
        ? `<img class="passport-photo" src="${data.passportPhotoUrl}" alt="Passport Photo" />`
        : `<div class="photo-placeholder">
        <div class="ph-icon">&#128247;</div>
        <div>Paste Photo Here</div>
        <div style="font-size:7px;">(Passport Size)</div>
      </div>`}
    </div>
  </div>
</div>

<!-- CONTACT DETAILS -->
<div class="section">
  <div class="section-hdr">Contact Details</div>
  <div class="section-body">
    <div class="field-grid fg-2" style="margin-bottom:4px;">
      ${fieldRow('Address', addressParts || null, 2)}
    </div>
    <div class="field-grid fg-4">
      ${fieldRow('Phone', data.phone)}
      ${fieldRow('Email', data.email)}
    </div>
  </div>
</div>

<!-- PARENT / GUARDIAN DETAILS -->
<div class="section">
  <div class="section-hdr">Parent / Guardian Details</div>
  <div class="section-body">
    <div class="field-grid fg-3" style="margin-bottom:4px;">
      ${fieldRow("Father's Name", data.fatherName)}
      ${fieldRow("Father's Phone", data.fatherPhone)}
      ${fieldRow("Father's Email", data.fatherEmail)}
    </div>
    <div class="field-grid fg-3">
      ${fieldRow("Mother's Name", data.motherName)}
      ${fieldRow("Mother's Phone", data.motherPhone)}
      ${fieldRow("Mother's Email", data.motherEmail)}
    </div>
  </div>
</div>

<!-- DOCUMENT CHECKLIST -->
<div class="section">
  <div class="section-hdr">Document Checklist</div>
  <div class="section-body" style="padding:0;">
    <table class="doc-checklist-table">
      <colgroup>
        <col style="width:5%;"><col style="width:27%;"><col style="width:9%;"><col style="width:9%;">
        <col style="width:5%;"><col style="width:27%;"><col style="width:9%;"><col style="width:9%;">
      </colgroup>
      <thead>
        <tr>
          <th>#</th>
          <th>Document</th>
          <th>Collected</th>
          <th>Status</th>
          <th>#</th>
          <th>Document</th>
          <th>Collected</th>
          <th>Status</th>
        </tr>
      </thead>
      <tbody>${docRows}</tbody>
    </table>
  </div>
</div>

<!-- DECLARATION -->
<div class="section">
  <div class="section-hdr">Declaration</div>
  <div class="section-body">
    <p class="decl-text">
      I, the undersigned, hereby declare that all the particulars furnished above are true and correct to the best of my knowledge
      and belief. I am aware that any misrepresentation or concealment of facts may result in cancellation of admission.
      I agree to abide by all the rules and regulations of <strong>${data.collegeName ?? 'SKS College Of Nursing'}</strong> as in force from time to time.
    </p>
    <div class="consent-row">
      <div class="consent-item">
        <div class="consent-box">${parentConsent === 'Yes' ? '&#10003;' : '&nbsp;'}</div>
        <span>Parent / Guardian Consent Given &nbsp;&nbsp;
          <strong>${parentConsent || 'No'}</strong>
        </span>
      </div>
      <div class="consent-item">
        <div class="consent-box">${studentConsent === 'Yes' ? '&#10003;' : '&nbsp;'}</div>
        <span>Applicant Consent Given &nbsp;&nbsp;
          <strong>${studentConsent || 'No'}</strong>
        </span>
      </div>
    </div>
    <div class="decl-meta">
      ${fieldRow('Place of Declaration', data.declarationPlace)}
      ${fieldRow('Date of Declaration', fmtDate(data.declarationDate))}
    </div>
  </div>
</div>

<!-- SIGNATURES -->
<div class="sig-section">
  <div class="sig-row">
    <div class="sig-block">
      <div class="sig-space"></div>
      <div class="sig-line">Parent / Guardian Signature</div>
    </div>
    <div class="sig-block">
      <div class="sig-seal">College Seal</div>
    </div>
    <div class="sig-block">
      <div class="sig-space"></div>
      <div class="sig-line">Authorized Signature</div>
    </div>
  </div>
</div>

<!-- FOOTER -->
<div class="form-footer">
  <span>Generated by OneCMS &ndash; SKS College of Nursing</span>
  <span>Admission No: ${data.admissionNumber} &nbsp;|&nbsp; Printed: ${new Date().toLocaleDateString('en-IN')}</span>
</div>

</div>
${autoPrint ? '<script>window.onload = function() { window.print(); };<\/script>' : ''}
</body>
</html>`;
}
// ─────────────────────────────────────────────────────────────────────────────
// Delivery: open the form HTML directly in a new browser window.
// The browser renders it perfectly with all CSS intact. Print / Save-as-PDF
// uses the browser's native print dialog (Ctrl+P / Cmd+P).
// ─────────────────────────────────────────────────────────────────────────────

type PdfDeliveryMode = 'save' | 'open' | 'print';

function deliverAdmissionForm(data: AdmissionFormData, mode: PdfDeliveryMode): void {
  const autoPrint = mode === 'print' || mode === 'save';
  const html = buildAdmissionFormHtml(data, autoPrint, false);
  const win = window.open('', '_blank');
  if (win) {
    win.document.write(html);
    win.document.close();
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// Public API — identical PDF rendering across all three delivery modes
// ─────────────────────────────────────────────────────────────────────────────

/** Opens the admission form in a new browser tab for viewing. */
export function viewAdmissionForm(data: AdmissionFormData): void {
  deliverAdmissionForm(data, 'open');
}

/** Opens the admission form in a new browser tab and triggers the print dialog. */
export function printAdmissionForm(data: AdmissionFormData): void {
  deliverAdmissionForm(data, 'print');
}

/** Opens the admission form in a new browser tab with the print dialog (Save as PDF). */
export function downloadAdmissionForm(data: AdmissionFormData): void {
  deliverAdmissionForm(data, 'save');
}
